"/* Mobile bottom navbar — visible only on mobile (≤768px) */
.mobile-nav {
  display: none;
}

@media (max-width: 768px) {
  .mobile-nav {
    display: flex;
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    z-index: 100;
    height: 64px;
    align-items: stretch;
    /* Glassmorphism matching existing design system */
    background: hsla(207, 73%, 4%, 0.72);
    backdrop-filter: blur(18px) brightness(1.1);
    -webkit-backdrop-filter: blur(18px) brightness(1.1);
    border-top: 0.5px solid rgba(255, 255, 255, 0.1);
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.08),
      0 -8px 32px rgba(0, 0, 0, 0.4);
    /* Safe area for notched phones */
    padding-bottom: env(safe-area-inset-bottom, 0px);
  }

  .mobile-nav-item {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 4px;
    background: none;
    border: none;
    height: auto;
    cursor: pointer;
    color: var(--text-more-muted);
    transition: color 0.2s ease, transform 0.15s ease;
    padding: 0;
    width: auto;
  }

  .mobile-nav-item span {
    font-family: "Inter", sans-serif;
    font-size: 10px;
    font-weight: 500;
    letter-spacing: 0.03em;
  }

  .mobile-nav-item svg {
    transition: transform 0.2s ease;
  }

  .mobile-nav-item:active svg {
    transform: scale(0.88);
  }

  .mobile-nav-item.active {
    color: var(--primary);
  }

  .mobile-nav-item.active svg {
    filter: drop-shadow(0 0 6px hsla(16, 100%, 56%, 0.55));
  }

  /* Push page content above the fixed nav */
  .root-container {
    padding-bottom: calc(64px + env(safe-area-inset-bottom, 0px) + 12px);
  }
}
"

"import "./Main.css";

// Components
import CompanySelection from "../CompanySelection/CompanySelection";
import BrandPlaybook from "../BrandPlaybook/BrandPlaybook";
import ContentManagement from "../ContentManagement/ContentManagement";

// Props
import { Company } from "../../../props";

// Modules
import { useState } from "react";

// Types
import { Tab } from "../MobileNav/MobileNav";

interface MainProps {
  activeTab: Tab;
}

function Main({ activeTab }: MainProps) {
  // Define state variable to manage state of selected company
  const [selectedCompany, setSelectedCompany] = useState<Company | null>(null);

  return (
    <main className="section main-section">
      <div className={`main-tab-panel${activeTab === "companies" ? " main-tab-panel--visible" : ""}`}>
        <CompanySelection
          selectedCompany={selectedCompany}
          onSelectCompany={setSelectedCompany}
        />
      </div>
      <div className={`main-tab-panel${activeTab === "playbook" ? " main-tab-panel--visible" : ""}`}>
        <BrandPlaybook selectedCompany={selectedCompany} />
      </div>
      <div className={`main-tab-panel${activeTab === "content" ? " main-tab-panel--visible" : ""}`}>
        <ContentManagement />
      </div>
    </main>
  );
}

export default Main;
"

".main-content {
  display: flex;
}

/* On desktop all panels are always visible */
.main-tab-panel {
  display: contents;
}

/* On mobile only the active panel shows */
@media (max-width: 768px) {
  .main-tab-panel {
    display: none;
    width: 100%;
  }

  .main-tab-panel--visible {
    display: block;
  }
}
